//! Reversible JPEG recompression (`pdfcraft-jxl`). The JPEG is a q90 encoding of a synthetic 256 x 128
//! gradient made for these tests (libjxl's `djxl`); nothing in it is third-party.

use pdfcraft_jxl::{Error, MAX_PIXELS, jpeg_frame, recompress_jpeg, reconstruct_jpeg};

#[test]
fn a_jpeg_becomes_a_smaller_jpeg_xl_file_and_comes_back_byte_for_byte() {
    let jxl = recompress_jpeg(JPEG).unwrap();
    assert!(jxl.len() < JPEG.len(), "{} -> {}", JPEG.len(), jxl.len());
    assert_eq!(reconstruct_jpeg(&jxl).unwrap().as_deref(), Some(JPEG));
}

#[test]
fn the_frame_header_is_read() {
    assert_eq!(jpeg_frame(JPEG), Some((256, 128, 3)));
    assert_eq!(jpeg_frame(&[0xFF, 0xD8]), None);
    assert_eq!(jpeg_frame(b"not a jpeg"), None);
}

#[test]
fn input_that_is_not_a_usable_jpeg_is_refused_without_a_panic() {
    for data in [&[][..], b"garbage garbage garbage", &JPEG[..JPEG.len() / 3], &JPEG[..200]] {
        assert!(recompress_jpeg(data).is_err(), "{} bytes", data.len());
    }
}

#[test]
fn a_frame_larger_than_the_limit_is_refused_before_anything_is_allocated() {
    // The same JPEG with its frame header claiming 65535 x 65535 pixels.
    let mut big = JPEG.to_vec();
    let at = big.windows(2).position(|w| w == [0xFF, 0xC0]).expect("baseline frame marker");
    big[at + 5..at + 9].copy_from_slice(&[0xFF, 0xFF, 0xFF, 0xFF]);
    assert!(u64::from(u16::MAX) * u64::from(u16::MAX) > MAX_PIXELS);
    assert_eq!(recompress_jpeg(&big), Err(Error::TooLarge));
}

#[test]
fn a_jpeg_xl_file_without_reconstruction_data_gives_none_and_garbage_gives_an_error() {
    assert_eq!(reconstruct_jpeg(LOSSLESS_JXL).unwrap(), None);
    assert!(reconstruct_jpeg(b"not a jpeg xl file").is_err());
    assert!(reconstruct_jpeg(&[]).is_err());
}

